// ❌ Lies to you for anything SQL-shaped
var options = new DbContextOptionsBuilder<AppDbContext>()
    .UseInMemoryDatabase("tests")
    .Options;

// ✅ Real relational semantics, still ephemeral (EF Core Sqlite package)
await using var connection = new SqliteConnection("DataSource=:memory:");
await connection.OpenAsync();                 // must stay open — closing drops the DB

var options = new DbContextOptionsBuilder<AppDbContext>()
    .UseSqlite(connection)
    .Options;

await using var db = new AppDbContext(options);
await db.Database.EnsureCreatedAsync();       // real schema, real constraints

// Unique index violations, FK enforcement, GROUP BY, transactions now behave like prod.

